import re

def parse(lines):
    sec_re = re.compile(r'^== (?P<s>.+?) ==\s*$')
    sub_re = re.compile(r'^-- (?P<s>.+?) --\s*$')
    dt_re = re.compile(r'^(?P<name>\S.*?)\s+\((?P<id>[\w.-]+)\)\s*$')
    rt_re = re.compile(r'^(?P<name>\S.*?) \((?P<version>\S+) - (?P<build>\S+)\) - (?P<id>\S+)(?:\s+\((?P<note>.*)\))?\s*$')
    dev_re = re.compile(r'^\s+(?P<name>\S.*?) \((?P<udid>[0-9A-Fa-f-]{36})\) \((?P<state>[^)]*)\)(?:\s+\((?P<note>.*)\))?\s*$')
    pair_re = re.compile(r'^(?P<udid>[0-9A-Fa-f-]{36}) \((?P<state>[^)]*)\)\s*$')
    mem_re = re.compile(r'^\s+(?P<role>Watch|Phone): (?P<name>\S.*?) \((?P<udid>[0-9A-Fa-f-]{36})\) \((?P<state>[^)]*)\)\s*$')
    dt = {'name': 'device_types', 'kind': 'table', 'lines': [], 'records': []}
    rt = {'name': 'runtimes', 'kind': 'table', 'lines': [], 'records': []}
    dv = {'name': 'devices', 'kind': 'table', 'lines': [], 'records': []}
    pr = {'name': 'device_pairs', 'kind': 'table', 'lines': [], 'records': []}
    skip = []
    sec = ''
    runtime = ''
    avail = 'available'
    cur = None
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        m = sec_re.match(l)
        if m:
            sec = m.group('s')
            skip.append(i)
            continue
        if sec == 'Device Types':
            m = dt_re.match(l)
            if m:
                dt['records'].append({'Name': m.group('name'), 'Identifier': m.group('id')})
                dt['lines'].append(i)
        elif sec == 'Runtimes':
            m = rt_re.match(l)
            if m:
                rt['records'].append({'Name': m.group('name'), 'Version': m.group('version'), 'Build': m.group('build'), 'Identifier': m.group('id'), 'Note': m.group('note') or ''})
                rt['lines'].append(i)
        elif sec == 'Devices':
            m = sub_re.match(l)
            if m:
                s = m.group('s')
                if s.startswith('Unavailable:'):
                    runtime = s.split(':', 1)[1].strip()
                    avail = 'unavailable'
                else:
                    runtime = s
                    avail = 'available'
                dv['lines'].append(i)
                continue
            m = dev_re.match(l)
            if m:
                dv['records'].append({'Runtime': runtime, 'Runtime Availability': avail, 'Name': m.group('name'), 'UDID': m.group('udid'), 'State': m.group('state'), 'Note': m.group('note') or ''})
                dv['lines'].append(i)
        elif sec == 'Device Pairs':
            m = pair_re.match(l)
            if m:
                cur = {'Pair UDID': m.group('udid'), 'Pair State': m.group('state'), 'Watch Name': '', 'Watch UDID': '', 'Watch State': '', 'Phone Name': '', 'Phone UDID': '', 'Phone State': ''}
                pr['records'].append(cur)
                pr['lines'].append(i)
                continue
            m = mem_re.match(l)
            if m and cur is not None:
                r = m.group('role')
                cur[r + ' Name'] = m.group('name')
                cur[r + ' UDID'] = m.group('udid')
                cur[r + ' State'] = m.group('state')
                pr['lines'].append(i)
    blocks = [b for b in (dt, rt, dv, pr) if b['lines']]
    return {'blocks': blocks, 'skip': skip}
